"""Known public/test signing key registry (§10.6), generated by scripts/build_known_keys.py."""

from __future__ import annotations

import json
from functools import lru_cache
from importlib import resources
from pathlib import Path
from typing import Any


def _registry_text() -> str:
    try:
        ref = resources.files("kloner").joinpath("data/known_keys.json")
        if ref.is_file():
            return ref.read_text(encoding="utf-8")
    except (FileNotFoundError, ModuleNotFoundError):
        pass
    repo = Path(__file__).resolve().parents[3] / "data" / "known_keys.json"
    return repo.read_text(encoding="utf-8")


@lru_cache(maxsize=1)
def registry() -> dict[str, Any]:
    data: dict[str, Any] = json.loads(_registry_text())
    return data


@lru_cache(maxsize=1)
def known_keys() -> dict[str, str]:
    """cert SHA-256 -> registry name (e.g. AOSP_TESTKEY)."""
    return {k["cert_sha256"]: k["name"] for k in registry().get("keys", [])}


def entry(cert_sha256: str) -> dict[str, Any] | None:
    for k in registry().get("keys", []):
        if k["cert_sha256"] == cert_sha256:
            return dict(k)
    return None
